def handle_type_a(item):
    value = item["value"] * 2
    category = "high" if value > 100 else "low"
    return {"id": item["id"], "value": value, "category": category}


def handle_type_b(item):
    value = item["value"] + 50
    return {"id": item["id"], "value": value, "category": "adjusted"}


def handle_type_c(item):
    if item["value"] < 0:
        return {"id": item["id"], "value": 0, "category": "clamped"}
    return {"id": item["id"], "value": item["value"], "category": "passthrough"}


HANDLERS = {
    "A": handle_type_a,
    "B": handle_type_b,
    "C": handle_type_c,
}


def dispatch(item):
    handler = HANDLERS.get(item.get("type"))
    if handler is None:
        return None
    return handler(item)


def process_data(data):
    return [result for item in data if (result := dispatch(item)) is not None]
