```typescript
// ─── Interfaces ────────────────────────────────────────────────────────────────

interface Preferences {
  theme: string;
  notifications: boolean;
  language: string;
}

interface User {
  id: number;
  name: string;
  email: string;
  preferences: Preferences;
  tags: string[];
  last_login: string; // ISO 8601
  metadata: Record<string, unknown> | null;
}

// ─── Validation ────────────────────────────────────────────────────────────────

function validateUser(user: unknown): user is User {
  if (user === null || typeof user !== "object") return false;

  const u = user as Record<string, unknown>;

  // id — integer
  if (typeof u["id"] !== "number" || !Number.isInteger(u["id"])) return false;

  // name — non-empty string
  if (typeof u["name"] !== "string" || u["name"].length === 0) return false;

  // email — must contain "@"
  if (typeof u["email"] !== "string" || !u["email"].includes("@")) return false;

  // preferences — nested object with typed fields
  if (
    u["preferences"] === null ||
    typeof u["preferences"] !== "object"
  )
    return false;
  const prefs = u["preferences"] as Record<string, unknown>;
  if (typeof prefs["theme"] !== "string") return false;
  if (typeof prefs["notifications"] !== "boolean") return false;
  if (typeof prefs["language"] !== "string") return false;

  // tags — array of strings
  if (!Array.isArray(u["tags"])) return false;
  if (!u["tags"].every((t) => typeof t === "string")) return false;

  // last_login — string (ISO 8601)
  if (typeof u["last_login"] !== "string") return false;

  // metadata — null or object
  if (
    u["metadata"] !== null &&
    typeof u["metadata"] !== "object"
  )
    return false;

  return true;
}
```

### Design Decisions

| Concern | Choice | Rationale |
|---|---|---|
| **`metadata`** | `Record<string, unknown> \| null` | `None` maps to `null` in TS; a record allows future extensibility while remaining type-safe |
| **`last_login`** | `string` (ISO 8601) | No built-in TS date type; string with ISO format is the standard interchange format |
| **Validation** | Type guard (`user is User`) | Returns a *narrowing* predicate so callers get full type safety after the check |
| **`email`** | `includes("@")` | Matches the observed validation rule; a full regex could be swapped in if stricter validation is needed |
| **`name`** | `length > 0` check | Mirrors the observed assertion that the name must be non-empty |
